import {createRequire} from 'node:module';import {resolve} from 'node:path';import {pathToFileURL} from 'node:url';import {mkdir,writeFile} from 'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');
const evidence=resolve('../../outputs/verification-v34-zone-diagnosis-v1');await mkdir(evidence);const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1200,height:860}});await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv33_TBD_vs_LAD_Core試合版.html')).href);await page.evaluate(()=>document.fonts.ready);
 const result=await page.evaluate(()=>{
  const auto=document.getElementById('auto-overhead');auto.checked=false;auto.dispatchEvent(new Event('change'));
  document.getElementById('managed-team').value='0';document.getElementById('batting-choice').value='take';
  for(let i=0;i<3;i++){document.getElementById('next-pitch').click();window.liveMatchPlayback.stop();}
  const api=window.liveMatchPlayback,records=api.inspect().host.history,result=[];
  for(let pitch=0;pitch<records.length;pitch++){
   const record=records[pitch],indices=record.frames.map((frame,index)=>({frame,index})).filter(value=>value.frame.phase==='pitch');const frameIndex=indices[Math.floor(indices.length/2)].index;
   api.seekPitch(pitch,frameIndex);
   for(const camera of ['catcher','mound','batter']){
    document.querySelector('[data-camera="'+camera+'"]').click();const s=api.inspect(),f=s.currentFrame,r=s.rendered;
    result.push({pitch:pitch+1,camera,renderedCamera:r.camera,frameIndex,tick:f.tick,phase:f.phase,ballKind:f.ballKind,fairKnown:f.fairKnown,
     zoneChecked:document.getElementById('zone').checked,autoOverhead:document.getElementById('auto-overhead').checked,
     ballPosition:f.ball?.position,batterId:f.batterPlayerId,actors:f.actors.filter(actor=>['P','C','batter'].includes(actor.role)),
     cameraEye:r.cameraEye,cameraYaw:r.cameraYaw,cameraPitch:r.cameraPitch,zoneCorners:r.zoneCorners,
     visibleCorners:r.zoneCorners.filter(p=>p&&p.x>=0&&p.x<=600&&p.y>=0&&p.y<=432).length,blockedZoneCells:r.blockedZoneCells.length});
   }
  }return result;
 });
 await page.locator('[data-camera="batter"]').click();await page.locator('.broadcast').screenshot({path:resolve(evidence,'third-pitch-batter.png')});await page.locator('[data-camera="catcher"]').click();await page.locator('.broadcast').screenshot({path:resolve(evidence,'third-pitch-catcher.png')});
 await writeFile(resolve(evidence,'zone-diagnosis.json'),JSON.stringify({artifact:'v33',mode:'three taken pitches, actual mid-pitch frame, auto-overhead false',observations:result},null,2)+'\n');
 console.log(JSON.stringify(result.map(value=>({pitch:value.pitch,camera:value.camera,rendered:value.renderedCamera,kind:value.ballKind,fair:value.fairKnown,zone:value.zoneCorners.length,visibleCorners:value.visibleCorners,eye:value.cameraEye,bounds:value.zoneCorners.map(p=>p&&[p.x,p.y])})),null,2));await page.close();
}finally{await browser.close();}
